import app from 'flarum/forum/app';
import AbstractPollList from '../AbstractPollList';
import PollListItem from './PollListItem';
export default class PollList extends AbstractPollList {
  className() {
    return 'PollList';
  }
  itemView(poll) {
    return m(PollListItem, {
      poll: poll
    });
  }
  emptyText() {
    return app.translator.trans('fof-polls.forum.polls_list.empty_text');
  }
  loadMoreText() {
    return app.translator.trans('fof-polls.forum.polls_list.load_more_button');
  }
}
flarum.reg.add('fof-polls', 'forum/components/Poll/PollList', PollList);