import app from 'flarum/forum/app';
import Hero from 'flarum/forum/components/Hero';
import LinkButton from 'flarum/common/components/LinkButton';
import ItemList from 'flarum/common/utils/ItemList';
export default class ComposeHero extends Hero {
  className() {
    return this.attrs.className;
  }
  bodyItems() {
    const items = new ItemList();
    const {
      item,
      translationPrefix
    } = this.attrs;
    items.add('title', m("h2", {
      className: "Hero-title"
    }, app.translator.trans(`${translationPrefix}.${item.id() ? 'edit' : 'add'}_title`)), 100);
    items.add('controls', m("div", {
      className: "ComposeHero-controls"
    }, this.controlItems().toArray()), 0);
    return items;
  }
  controlItems() {
    const items = new ItemList();
    const {
      item,
      managerRoute,
      managerIcon,
      managerLabel,
      viewRoute,
      viewIcon,
      viewLabel
    } = this.attrs;
    items.add('manager', m(LinkButton, {
      icon: managerIcon,
      className: "Button Button--secondary",
      href: app.route(managerRoute)
    }, managerLabel), 100);
    if (item.exists && viewRoute && viewLabel) {
      items.add('view', m(LinkButton, {
        icon: viewIcon || 'far fa-arrow-up-right-from-square',
        className: "Button Button--secondary",
        href: app.route(viewRoute, {
          id: item.id()
        })
      }, viewLabel), 50);
    }
    return items;
  }
}
flarum.reg.add('fof-polls', 'forum/components/ComposeHero', ComposeHero);