import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Separator from 'flarum/common/components/Separator';
import ItemList from 'flarum/common/utils/ItemList';
import extractText from 'flarum/common/utils/extractText';
import ComposePollGroupPage from '../components/ComposePollGroupPage';
import PollGroupListState from '../states/PollGroupListState';
export default {
  controls(pollGroup, context) {
    const items = new ItemList();
    const sections = ['moderation', 'destructive'];
    sections.forEach(section => {
      const controls = this[`${section}Controls`](pollGroup, context).toArray();
      if (!controls.length) return;
      controls.forEach(item => items.add(item.itemName, item));
      items.add(`${section}Separator`, m(Separator, null));
    });
    return items;
  },
  moderationControls(pollGroup, context) {
    const items = new ItemList();
    if (pollGroup.canEdit()) {
      items.add('edit', m(Button, {
        icon: "fas fa-pencil-alt",
        onclick: this.editAction.bind(this, pollGroup)
      }, app.translator.trans('fof-polls.forum.poll_groups.controls.edit_label')));
      items.add('addPoll', m(Button, {
        icon: "fas fa-plus",
        onclick: this.addPoll.bind(this, pollGroup)
      }, app.translator.trans('fof-polls.forum.poll_groups.controls.add_poll_label')));
      items.add('view', m(Button, {
        icon: "far fa-arrow-up-right-from-square",
        onclick: () => m.route.set(app.route('fof.polls.groups.view', {
          id: pollGroup.id()
        }))
      }, app.translator.trans('fof-polls.forum.poll_groups.controls.view_label')));
    }
    return items;
  },
  destructiveControls(pollGroup, context) {
    const items = new ItemList();
    if (pollGroup.canDelete()) {
      items.add('delete', m(Button, {
        icon: "far fa-trash-alt",
        onclick: this.deleteAction.bind(this, pollGroup)
      }, app.translator.trans('fof-polls.forum.poll_groups.controls.delete_label')));
    }
    return items;
  },
  editAction(pollGroup) {
    m.route.set(app.route('fof.polls.groups.composer', {
      id: pollGroup.id()
    }));
  },
  async deleteAction(pollGroup) {
    if (!confirm(extractText(app.translator.trans('fof-polls.forum.poll_groups.controls.delete_confirmation')))) {
      return;
    }
    return pollGroup.delete().then(() => {
      this.alert('success', 'fof-polls.forum.poll_groups.controls.delete_success_message');
      if (app.current.matches(ComposePollGroupPage, {
        id: pollGroup.id()
      })) {
        m.route.set(app.route('fof.polls.groups.list'));
      } else {
        PollGroupListState.notifyDeleted(pollGroup);
      }
    }).catch(() => this.alert('error', 'fof-polls.forum.poll_groups.controls.delete_error_message'));
  },
  addPoll(pollGroup) {
    app.modal.show(() => import(/* webpackChunkName: 'forum/components/CreatePollModal', webpackMode: 'lazy-once' */ '../components/CreatePollModal'), {
      onsubmit: data => app.store.createRecord('polls').save({
        ...data,
        relationships: {
          pollGroup
        }
      }, {
        data: {
          include: 'options,myVotes,myVotes.option'
        }
      }).then(poll => {
        pollGroup.rawRelationship('polls')?.push?.({
          type: 'polls',
          id: poll.id()
        });
        m.redraw();
      })
    });
  },
  alert(type, key) {
    const id = app.alerts.show({
      type
    }, app.translator.trans(key));
    if (type === 'success') setTimeout(() => app.alerts.dismiss(id), 10000);
  }
};